/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: entry, view, summary
 *   Constants: slot, slotTwo, release, key, groupKey
 * Tests
 *   - a server-shaped lookup view parses strictly, before any run as null too
 *   - extra keys, links, forged paths, unknown states and oversized lists are refused
 *   - the summary state is strict: no missing or extra field, unknown tick or forged suggestion ID
 *   - proposals, ID conflicts and the found names carry MusicBrainz IDs, defaulting to none for a server that sends none
 *   - a candidate's artwork flag and the cover-staging wait default to false for a server that sends neither, and are never addresses
 *   - an iTunes-only candidate parses with its collection ID, source and not-checked mark agreeing with its key, and the iTunes status defaults to not queried
 *   - an append target's expected rows parse strictly within their bounds, and a server that sends none reads as null
 *   - an import view refuses everything only a review view carries: the catalog trigger, the exact-count basis, review paths, precision, pairs, subset comparisons, the track-title mark, progress and the timeline
 *   - a review candidate says whether a track-title search first found its release, false from a server that sends none, and only as a boolean
 *   - a submitted run's Artist name parses in import and review views within 1000 characters; a view without it reads as none
 * @end-catalog */

import { lookupResponseSchema, lookupViewSchema, reviewLookupViewSchema } from './importLookupApi';

const slot = '10000000-0000-4000-8000-000000000001', slotTwo = '10000000-0000-4000-8000-000000000002';
const release = '0000000b-0000-4000-8000-000000000001', key = `musicbrainz:${release}`, groupKey = 'a'.repeat(64);
const entry = (name: string, keyNumber: number, joinPhrase: string | null = null) =>
  ({ key: `30000000-0000-4000-8000-00000000000${keyNumber}`, name, role: 'primary', joinPhrase, musicBrainzId: null });
/** A view shaped as the server's allowlist returns it (src/administration/lookup/lookupView.ts), with one answered and one open conflict. */
const view = () => ({
  run: 2, state: 'complete', issue: null, outcome: 'candidates', input: { trigger: 'submitted', submitted: { kind: 'album', text: 'Synthetic Album' } },
  candidates: [{ key, releaseId: release, status: 'matching', title: 'Synthetic Album', artist: 'Synthetic Lead & Synthetic Second', label: 'Synthetic Label',
    catalogNumber: 'SYN-001', barcode: '4006381333931', country: 'JP', date: { year: 2021, month: 5, day: 1 }, formats: ['CD'], trackCount: 2,
    comparison: { trackCount: { local: 2, candidate: 2 }, discCount: { local: null, candidate: 1 }, differences: [], unknownLocalDurations: 0, unknownCandidateDurations: 0 },
    groupKey, artistMismatch: false }],
  groups: [{ groupKey, representativeKey: key, memberKeys: [key], proposal: { albumTitle: 'Synthetic Album',
    artists: [{ name: 'Synthetic Lead', role: 'primary', joinPhrase: ' & ' }, { name: 'Synthetic Second', role: 'primary', joinPhrase: null }], label: 'Synthetic Label',
    releaseDate: { year: 2020, month: null, day: null }, tracks: [{ discNumber: 1, trackNumber: 1, title: 'First Song' }, { discNumber: 1, trackNumber: 2, title: 'Second Song' }] } }],
  preselection: { candidateKey: key, basis: 'onlyMatchingGroup', artistMismatch: false },
  disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 2, partialComparison: false },
  applied: { run: 2, candidateKey: key, releaseId: release, choice: 'preselected', basis: 'onlyMatchingGroup',
    values: [{ path: 'album.title', slotId: null }, { path: `tracks.${slot}.title`, slotId: slot }],
    conflicts: [{ path: 'album.label', slotId: null, lookup: { name: 'Synthetic Label', musicBrainzId: null }, answer: null },
      { path: 'album.artists', slotId: null, lookup: [entry('Synthetic Lead', 1, ' & '), entry('Synthetic Second', 2)], answer: 'mine' },
      { path: `tracks.${slotTwo}.trackNumber`, slotId: slotTwo, lookup: 2, answer: null }],
    flagged: [{ path: 'album.releaseDate', reason: 'format' }] },
  staleFiles: [slotTwo], needsAnswer: { tie: false, conflicts: ['album.label', `tracks.${slotTwo}.trackNumber`] }, blocking: true
});

/** The summary state as src/administration/import/adminImportSummary.ts returns it. */
const summary = () => ({ append: false, waiting: { uploads: false, lookup: true, analysis: false }, placeholderOnly: false,
  luna: [{ id: 'c'.repeat(24), tick: 'ticked' }, { id: 'd'.repeat(24), tick: 'conflict' }], analysis: { runs: 1, attempts: 20, daily: 218 }, lookupAvailable: true, identityAnswers: 2 });

test('a server-shaped lookup view parses strictly, before any run as null too', () => {
  expect(lookupResponseSchema.safeParse({ lookup: view(), revision: 7, valueRevision: 3, summary: summary() }).success).toBe(true);
  expect(lookupResponseSchema.safeParse({ lookup: null, revision: 1, valueRevision: 0, summary: summary() }).success).toBe(true);
  expect(lookupViewSchema.safeParse({ ...view(), applied: null, preselection: null, disclosure: null, candidates: [], groups: [] }).success).toBe(true);
});

test('extra keys, links, forged paths, unknown states and oversized lists are refused', () => {
  const item = view();
  const refused = (value: unknown) => expect(lookupViewSchema.safeParse(value).success).toBe(false);
  refused({ ...item, fence: 3 });
  refused({ ...item, candidates: [{ ...item.candidates[0], url: 'https://musicbrainz.org/release/x' }] });
  refused({ ...item, candidates: [{ ...item.candidates[0], artworkUrl: 'https://is1-ssl.mzstatic.com/x.jpg' }] });
  refused({ ...item, applied: { ...item.applied, actorId: 'aaaaaaaaaaaaaaaaaaaaaaaa' } });
  refused({ ...item, applied: { ...item.applied, values: [{ path: 'album.visibility', slotId: null }] } });
  refused({ ...item, applied: { ...item.applied, values: [{ path: 'tracks.not-a-slot.title', slotId: null }] } });
  refused({ ...item, needsAnswer: { tie: false, conflicts: ['__proto__'] } });
  refused({ ...item, applied: { ...item.applied, conflicts: [{ ...item.applied.conflicts[0], lookup: { name: 'x', musicBrainzId: null, url: 'https://example.invalid' } }] } });
  refused({ ...item, state: 'paused' });
  // The disclosure says whether the comparison was partial, always as a boolean.
  refused({ ...item, disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 2 } });
  refused({ ...item, disclosure: { ...item.disclosure, partialComparison: 'yes' } });
  expect(lookupViewSchema.safeParse({ ...item, disclosure: { ...item.disclosure, partialComparison: true } }).success).toBe(true);
  refused({ ...item, candidates: [{ ...item.candidates[0], key: 'itunes:1' }] });
  refused({ ...item, candidates: Array.from({ length: 26 }, () => item.candidates[0]) });
  refused({ ...item, groups: Array.from({ length: 26 }, () => item.groups[0]) });
  refused({ ...item, candidates: [{ ...item.candidates[0], formats: Array.from({ length: 21 }, () => 'CD') }] });
  refused({ ...item, candidates: [{ ...item.candidates[0], title: 't'.repeat(1001) }] });
  refused({ ...item, applied: { ...item.applied, flagged: Array.from({ length: 306 }, () => item.applied.flagged[0]) } });
  expect(lookupResponseSchema.safeParse({ lookup: item, revision: 1, valueRevision: 0, summary: summary(), records: [] }).success).toBe(false);
});

test('the summary state is strict: no missing or extra field, unknown tick or forged suggestion ID', () => {
  const refused = (value: unknown) => expect(lookupResponseSchema.safeParse({ lookup: null, revision: 1, valueRevision: 0, summary: value }).success).toBe(false);
  const item = summary();
  expect(lookupResponseSchema.safeParse({ lookup: null, revision: 1, valueRevision: 0 }).success).toBe(false);
  refused({ ...item, publishable: true });
  refused({ ...item, waiting: { ...item.waiting, staging: true } }); refused({ ...item, waiting: { ...item.waiting, cover: 'yes' } });
  refused({ ...item, luna: [{ id: 'c'.repeat(24), tick: 'maybe' }] });
  refused({ ...item, luna: [{ id: '__proto__', tick: 'ticked' }] });
  refused({ ...item, analysis: { runs: -1, attempts: 0, daily: 0 } });
  refused({ ...item, placeholderOnly: undefined });
  refused({ ...item, lookupAvailable: undefined }); refused({ ...item, identityAnswers: 1.5 }); refused({ ...item, identityAnswers: -1 });
});

test('proposals, ID conflicts and the found names carry MusicBrainz IDs, defaulting to none for a server that sends none', () => {
  const mbid = '00000000-0000-4000-8000-0000000000a1', base = view();
  const parsed = lookupResponseSchema.parse({ lookup: base, revision: 7, valueRevision: 3, summary: summary() });
  expect([parsed.lookup!.groups[0].proposal.artists[0].musicBrainzId, parsed.lookup!.groups[0].proposal.labelMusicBrainzId, parsed.lookup!.applied!.conflicts[0].musicBrainzId, parsed.musicBrainzNames])
    .toEqual([null, null, false, []]);
  const identified = { ...base, groups: [{ ...base.groups[0], proposal: { ...base.groups[0].proposal, labelMusicBrainzId: mbid, artists: base.groups[0].proposal.artists.map(artist => ({ ...artist, musicBrainzId: mbid })) } }],
    applied: { ...base.applied, conflicts: [{ ...base.applied.conflicts[0], lookup: { name: 'Synthetic Label', musicBrainzId: mbid }, musicBrainzId: true }] } };
  expect(lookupResponseSchema.safeParse({ lookup: identified, revision: 7, valueRevision: 3, summary: summary(), musicBrainzNames: [{ musicBrainzId: mbid, names: ['Synthetic Lead', 'リード'] }] }).success).toBe(true);
  for (const musicBrainzNames of [[{ musicBrainzId: 'x', names: [] }], [{ musicBrainzId: mbid, names: ['n'.repeat(201)] }], [{ musicBrainzId: mbid, names: Array(33).fill('n') }],
    Array(22).fill({ musicBrainzId: mbid, names: [] }), [{ musicBrainzId: mbid, names: [], extra: 1 }]])
    expect(lookupResponseSchema.safeParse({ lookup: null, revision: 1, valueRevision: 0, summary: summary(), musicBrainzNames }).success).toBe(false);
  expect(lookupViewSchema.safeParse({ ...base, groups: [{ ...base.groups[0], proposal: { ...base.groups[0].proposal, labelMusicBrainzId: 'X' } }] }).success).toBe(false);
});

test('a candidate\'s artwork flag and the cover-staging wait default to false for a server that sends neither, and are never addresses', () => {
  const parsed = lookupResponseSchema.parse({ lookup: view(), revision: 7, valueRevision: 3, summary: summary() });
  expect([parsed.lookup!.candidates[0].artwork, parsed.summary.waiting.cover]).toEqual([false, false]);
  const base = view(), shown = { ...base, candidates: [{ ...base.candidates[0], artwork: true }] };
  const waiting = { ...summary(), waiting: { uploads: false, lookup: false, cover: true, analysis: false } };
  const read = lookupResponseSchema.parse({ lookup: shown, revision: 7, valueRevision: 3, summary: waiting });
  expect([read.lookup!.candidates[0].artwork, read.summary.waiting.cover]).toEqual([true, true]);
  for (const artwork of ['https://coverartarchive.org/release/x/front-500', 1, null]) {
    expect(lookupViewSchema.safeParse({ ...base, candidates: [{ ...base.candidates[0], artwork }] }).success).toBe(false);
  }
});

test('an iTunes-only candidate parses with its collection ID, source and not-checked mark agreeing with its key, and the iTunes status defaults to not queried', () => {
  const item = view(), itunes = { ...item.candidates[0], key: 'itunes:1689358563', releaseId: '1689358563', source: 'itunes', notChecked: true, label: null, catalogNumber: null, country: null, formats: [] };
  const parsed = lookupViewSchema.parse({ ...item, candidates: [itunes], groups: [], preselection: { candidateKey: itunes.key, basis: 'onlyMatchingGroup', artistMismatch: false, notChecked: true },
    applied: { ...item.applied, candidateKey: itunes.key, releaseId: itunes.releaseId, source: 'itunes', notChecked: true }, itunes: 'answered' });
  expect([parsed.candidates[0].source, parsed.candidates[0].notChecked, parsed.preselection!.notChecked, parsed.applied!.source, parsed.applied!.notChecked, parsed.itunes])
    .toEqual(['itunes', true, true, 'itunes', true, 'answered']);
  // A server that sends none of these: MusicBrainz candidates, checked, iTunes not queried.
  const plain = lookupViewSchema.parse(item);
  expect([plain.candidates[0].source, plain.candidates[0].notChecked, plain.preselection!.notChecked, plain.applied!.source, plain.applied!.notChecked, plain.itunes])
    .toEqual(['musicbrainz', false, false, 'musicbrainz', false, 'notQueried']);
  const refused = (candidate: Record<string, unknown>) => expect(lookupViewSchema.safeParse({ ...item, candidates: [candidate], groups: [], preselection: null }).success).toBe(false);
  // Key, source and release ID must agree; a collection ID has 1 to 12 digits without a leading zero; no address is ever accepted.
  refused({ ...itunes, releaseId: '1689358564' });
  refused({ ...itunes, source: 'musicbrainz' });
  refused({ ...itunes, key: 'itunes:0', releaseId: '0' });
  refused({ ...itunes, key: 'itunes:01689358563', releaseId: '01689358563' });
  refused({ ...itunes, key: 'itunes:1234567890123', releaseId: '1234567890123' });
  refused({ ...itunes, artworkUrl: 'https://is1-ssl.mzstatic.com/image/thumb/x/100x100bb.jpg' });
  refused({ ...itunes, storefront: 'jp' });
  expect(lookupViewSchema.safeParse({ ...item, itunes: 'searching' }).success).toBe(false);
  // A MusicBrainz ID is still required where one is named: never a collection ID.
  expect(lookupResponseSchema.safeParse({ lookup: null, revision: 1, valueRevision: 0, summary: summary(), musicBrainzNames: [{ musicBrainzId: '1689358563', names: [] }] }).success).toBe(false);
});

test('an append target\'s expected rows parse strictly within their bounds, and a server that sends none reads as null', () => {
  const tracklist = () => ({ albumId: 'a'.repeat(24), durationToleranceMs: 3000,
    rows: [{ discNumber: 1, trackNumber: 1, title: 'First Row', durationMs: 200_000, filled: true }, { discNumber: 1, trackNumber: 2, title: 'Second Row', durationMs: null, filled: false }],
    files: [{ slotId: slot, durationMs: 241_000, durationPrecisionMs: 1000, appended: true }, { slotId: slotTwo, durationMs: null, durationPrecisionMs: 0, appended: false }],
    numbering: [{ slotId: slot, discNumber: 1, trackNumber: 2, title: 'Second Row' }, { slotId: slotTwo, discNumber: 1, trackNumber: 3, title: null }] });
  const parse = (value: unknown) => lookupResponseSchema.safeParse({ lookup: null, revision: 1, valueRevision: 0, summary: { ...summary(), appendTracklist: value } });
  expect(parse(tracklist()).data?.summary.appendTracklist).toEqual(tracklist());
  expect(parse(null).data?.summary.appendTracklist).toBeNull();
  expect(lookupResponseSchema.parse({ lookup: null, revision: 1, valueRevision: 0, summary: summary() }).summary.appendTracklist).toBeNull();
  const refused = (edit: (value: ReturnType<typeof tracklist>) => void) => { const value = tracklist(); edit(value); expect(parse(value).success).toBe(false); };
  refused(value => Object.assign(value, { source: 'musicbrainz' }));
  refused(value => Object.assign(value.rows[0], { memberIds: [] }));
  refused(value => Object.assign(value.files[0], { filename: '01.flac' }));
  refused(value => { value.rows = Array.from({ length: 101 }, (_row, index) => ({ discNumber: 1, trackNumber: index + 1, title: 'Row', durationMs: null, filled: false })); });
  refused(value => { value.rows = []; });
  refused(value => { value.files[0].slotId = 'not-a-slot'; });
  refused(value => { value.numbering[0].slotId = '../album'; });
  refused(value => { value.rows[0].trackNumber = 0; });
  refused(value => { value.rows[0].discNumber = 1000; });
  refused(value => { value.numbering[0].trackNumber = 10_000; });
  refused(value => { value.rows[0].title = 'x'.repeat(301); });
  refused(value => { value.rows[0].durationMs = 1.5; });
  refused(value => { value.files[0].durationMs = 0; });
  refused(value => { (value.files[0] as { durationPrecisionMs: number }).durationPrecisionMs = 500; });
  refused(value => { value.numbering[0].title = ''; });
  refused(value => { value.albumId = 'A'.repeat(24); });
  refused(value => { value.durationToleranceMs = 60_001; });
});

test('an import view refuses everything only a review view carries: the catalog trigger, the exact-count basis, review paths, precision, pairs, subset comparisons, the track-title mark, progress and the timeline', () => {
  const item = view(), refused = (value: unknown) => expect(lookupViewSchema.safeParse(value).success).toBe(false);
  refused({ ...item, input: { trigger: 'catalog', submitted: null } });
  refused({ ...item, preselection: { ...item.preselection, basis: 'exactTrackCount' } });
  refused({ ...item, applied: { ...item.applied, basis: 'exactTrackCount' } });
  refused({ ...item, applied: { ...item.applied, values: [{ path: 'album.expectedTracklist', slotId: null }] } });
  refused({ ...item, applied: { ...item.applied, values: [{ path: `tracks.${slot}.artists`, slotId: slot }] } });
  refused({ ...item, needsAnswer: { tie: false, conflicts: [`tracks.${slot}.artists`] } });
  refused({ ...item, applied: { ...item.applied, conflicts: [{ ...item.applied.conflicts[0], precision: false }] } });
  refused({ ...item, applied: { ...item.applied, flagged: [{ path: 'album.label', reason: 'notApplicable' }] } });
  refused({ ...item, applied: { ...item.applied, pairs: null } });
  refused({ ...item, candidates: [{ ...item.candidates[0], comparison: { ...item.candidates[0].comparison, subset: null } }] });
  refused({ ...item, candidates: [{ ...item.candidates[0], comparison: { ...item.candidates[0].comparison, differences: ['pairing'] } }] });
  refused({ ...item, candidates: [{ ...item.candidates[0], byTrackTitle: false }] });
  refused({ ...item, state: 'running', progress: { phase: 'search', done: 0, total: 1, startedAt: '2026-10-25T00:00:00.000Z', updatedAt: '2026-10-25T00:00:00.000Z' } });
  refused({ ...item, timeline: { steps: [], startedAt: '2026-10-25T00:00:00.000Z', updatedAt: '2026-10-25T00:00:00.000Z', completedAt: null, retry: null } });
  refused({ ...item, candidates: [{ ...item.candidates[0], comparison: { ...item.candidates[0].comparison,
    subset: { leftOutTracks: 0, pairing: 'unique', pairs: [], missingTrackCount: 0, unpairableSlotIds: [], pairedBy: 'titlePositions' } } }] });
});

test('a review candidate says whether a track-title search first found its release, false from a server that sends none, and only as a boolean', () => {
  const item = view(), candidate = { ...item.candidates[0], comparison: { ...item.candidates[0].comparison, subset: null } };
  // A review view without an application yet: the parts the two modes share.
  const review = (extra: Record<string, unknown>) => reviewLookupViewSchema.safeParse({ ...item, applied: null, candidates: [{ ...candidate, ...extra }] });
  const marked = review({ byTrackTitle: true }), plain = review({});
  expect(marked.success && marked.data.candidates[0].byTrackTitle).toBe(true);
  expect(plain.success && plain.data.candidates[0].byTrackTitle).toBe(false);
  for (const value of ['true', 1, null]) expect(review({ byTrackTitle: value }).success).toBe(false);
});

test('a submitted run\'s Artist name parses in import and review views within 1000 characters; a view without it reads as none', () => {
  // A review view with no candidate or application yet: the parts the two modes share.
  const reviewView = () => ({ ...view(), candidates: [], groups: [], preselection: null, disclosure: null, applied: null, needsAnswer: { tie: false, conflicts: [] } });
  const submitted = (artist?: unknown) => ({ kind: 'album', text: 'Synthetic Album', ...(artist === undefined ? {} : { artist }) });
  for (const [schema, base] of [[lookupViewSchema, view], [reviewLookupViewSchema, reviewView]] as const) {
    const typed = schema.safeParse({ ...base(), input: { trigger: 'submitted', submitted: submitted('Synthetic Ensemble') } });
    expect(typed.success && typed.data.input.submitted?.artist).toBe('Synthetic Ensemble');
    expect(schema.safeParse({ ...base(), input: { trigger: 'submitted', submitted: submitted('x'.repeat(1000)) } }).success).toBe(true);
    const plain = schema.safeParse({ ...base(), input: { trigger: 'submitted', submitted: submitted() } });
    expect(plain.success && (plain.data.input.submitted?.artist ?? null)).toBeNull();
    for (const artist of ['x'.repeat(1001), 7, null]) {
      expect(schema.safeParse({ ...base(), input: { trigger: 'submitted', submitted: submitted(artist) } }).success).toBe(false);
    }
    expect(schema.safeParse({ ...base(), input: { trigger: 'submitted', submitted: { ...submitted('Synthetic Ensemble'), label: 'Synthetic Label' } } }).success).toBe(false);
  }
});
